package com.project.w_3d_world.features.wallet.dto;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant; import java.util.List;
public final class WalletDtos { private WalletDtos(){} public record WalletResponse(int userId,Integer walletId,BigDecimal minimumReserve,BigDecimal withdrawableBalance,BigDecimal pendingBalance,BigDecimal availableBalance,BigDecimal payoutHold,BigDecimal returnShippingDebt,List<EarningResponse> earnings){} public record EarningResponse(int orderId,BigDecimal grossAmount,BigDecimal commissionRate,BigDecimal commissionAmount,BigDecimal netAmount,String status,Instant eligibleAt,Instant releasedAt){} public record PayoutRequest(@NotNull @DecimalMin("0.01") @Digits(integer=16,fraction=2) BigDecimal amount,@NotNull @Positive Integer bankAccountId,@NotBlank @Size(max=1000) String reason){} public record PayoutDecision(@NotNull Boolean approved,@NotBlank @Size(max=1000) String reason,@Size(max=255) String transferReference){} public record PayoutResponse(int transactionId,BigDecimal amount,String status,Integer bankAccountId,String transferReference){} }
